// Normalize the item shape from the caller and stamp flow constants.
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const FLOW = 'Fieldfolio Draft Recovery';
const RECOVERY_TAG = 'Draft-Fieldfolio-Recovery';
const today = new Date().toISOString().slice(0, 10);

return $input.all().map((it) => {
  const j = it.json || {};
  const email = String(j.email || '').trim().toLowerCase();
  const accountName = String(j.accountName || j.businessName || '').trim();
  return { json: {
    accountNo: String(j.accountNo || '').trim(),
    accountName,
    businessName: String(j.businessName || accountName).trim(),
    email,
    emailValid: !!email && EMAIL_RE.test(email),
    source: j.source || 'fieldfolio_draft_order',
    sourceEmailId: String(j.sourceEmailId || '').trim(),
    draftOrderDate: j.draftOrderDate || today,
    flow: FLOW,
    recoveryTag: RECOVERY_TAG,
  } };
});

// Index tracker rows by lowercased email (scoped to this flow),
// then classify every input customer: start or skip (with reason).
const flow = 'Fieldfolio Draft Recovery';
const trackerRows = $('Read Engagement Tracker').all().map((r) => r.json || {});

const idx = new Map();
for (const r of trackerRows) {
  const email = String(r.Email || r.email || '').trim().toLowerCase();
  if (!email) continue;
  const rowFlow = String(r.Flow || '').trim();
  if (rowFlow && rowFlow !== flow) continue;
  const prev = idx.get(email);
  const status = String(r.Status || '').trim();
  // Active wins; otherwise last-write-wins as a fallback.
  if (!prev || status === 'Active') idx.set(email, r);
}

const items = $input.all();
return items.map((it) => {
  const c = { ...it.json };
  c._action = 'start';
  c._reason = 'new-customer';
  if (!c.emailValid) {
    c._action = 'skip'; c._reason = 'invalid-email';
    return { json: c };
  }
  const existing = idx.get(c.email);
  if (existing) {
    const st = String(existing.Status || '').trim();
    if (st === 'Active')       { c._action = 'skip'; c._reason = 'already-active'; }
    else if (st === 'Converted')    { c._action = 'skip'; c._reason = 'already-converted'; }
    else if (st === 'Unresponsive') { c._action = 'skip'; c._reason = 'previously-unresponsive'; }
    else if (st === 'Escalated')    { c._action = 'skip'; c._reason = 'previously-escalated'; }
    // Any other/blank status falls through to 'start'.
  }
  return { json: c };
});

// Shape input for the `mailchimp tags update` sub-workflow.
// It accepts { email, tags: [...] } and reconciles the member's tags.
return $input.all().map((it) => {
  const c = it.json;
  return { json: {
    email: c.email,
    tags: [c.recoveryTag],
    accountName: c.accountName,
    accountNo: c.accountNo,
    source: c.source,
  } };
});

// Build tracker rows for every customer we actually started recovery for.
// Reads from Decide Action so it is immune to the sub-workflow's output shape.
const now = new Date().toISOString();
const starts = $('Decide Action').all()
  .filter((it) => it.json._action === 'start')
  .map((it) => {
    const c = it.json;
    return { json: {
      AccountNo: c.accountNo,
      AccountName: c.accountName,
      Email: c.email,
      Flow: c.flow,
      Step: 1,
      Status: 'Active',
      LastEmailSent: now,
      LastOrderDate: c.draftOrderDate,
      RecoveryStartedAt: now,
      RecoveryCompletedAt: '',
      Source: 'Fieldfolio',
      SourceEmailId: c.sourceEmailId,
      UpdatedAt: now,
    } };
  });
return starts.length ? starts : [{ json: { _empty: true } }];

// Roll up the run for observability. Nothing depends on this shape;
// it is the workflow's return value to the caller.
const decisions = $('Decide Action').all().map((it) => it.json);
const started = decisions.filter((d) => d._action === 'start').length;
const skipped = decisions.length - started;
const skippedBy = {};
for (const d of decisions) {
  if (d._action === 'start') continue;
  skippedBy[d._reason] = (skippedBy[d._reason] || 0) + 1;
}
return [{ json: {
  flow: 'Fieldfolio Draft Recovery',
  total: decisions.length,
  started,
  skipped,
  skippedBy,
  at: new Date().toISOString(),
} }];
